#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>
#include <memory>
#include <cstring>
#include <openssl/hmac.h>
#include <openssl/evp.h>
#include <openssl/rand.h>

namespace search_index {

struct ServiceCredential {
    std::string service_id;
    unsigned char key[32];
    uint64_t issued_at;
    uint64_t expires_at;
};

class KeyDerivation {
public:
    static bool derive_signing_key(const unsigned char* master_key,
                                   const std::string& context,
                                   uint64_t epoch,
                                   unsigned char* out_key, size_t out_len) {
        std::string label = "search-index-auth-v2";
        // KDF: HMAC(master, label || context || epoch)
        unsigned char info[256];
        size_t info_len = 0;
        memcpy(info + info_len, label.data(), label.size());
        info_len += label.size();
        memcpy(info + info_len, context.data(), context.size());
        info_len += context.size();
        memcpy(info + info_len, &epoch, sizeof(epoch));
        info_len += sizeof(epoch);

        unsigned int hmac_len = 0;
        unsigned char* result = HMAC(EVP_sha256(), master_key, 32,
                                     info, info_len, out_key, &hmac_len);
        return result != nullptr && hmac_len == out_len;
    }
};

class AuthTokenGenerator {
private:
    unsigned char master_key_[32];
    uint64_t current_epoch_;

public:
    AuthTokenGenerator() : current_epoch_(0) {
        RAND_bytes(master_key_, sizeof(master_key_));
    }

    ServiceCredential issue_credential(const std::string& service_id,
                                        uint64_t validity_secs) {
        ServiceCredential cred;
        cred.service_id = service_id;
        cred.issued_at = time(nullptr);
        cred.expires_at = cred.issued_at + validity_secs;

        // Derive per-service key from master using service context
        KeyDerivation::derive_signing_key(
            master_key_, service_id, current_epoch_,
            cred.key, sizeof(cred.key));

        return cred;
    }

    void rotate_epoch() { current_epoch_++; }
    uint64_t epoch() const { return current_epoch_; }
};

class CrossServiceAuthenticator {
private:
    std::unordered_map<std::string, ServiceCredential> credentials_;
    AuthTokenGenerator* generator_;

public:
    CrossServiceAuthenticator(AuthTokenGenerator* gen) : generator_(gen) {}

    bool register_service(const std::string& service_id) {
        auto cred = generator_->issue_credential(service_id, 3600);
        credentials_[service_id] = cred;
        return true;
    }

    std::string create_auth_token(const std::string& from_service,
                                   const std::string& to_service,
                                   const std::string& payload) {
        auto it = credentials_.find(from_service);
        if (it == credentials_.end()) return "";

        // Sign: HMAC(service_key, to_service || payload)
        unsigned char mac[32];
        unsigned int mac_len = 0;
        std::string data = to_service + payload;

        HMAC(EVP_sha256(), it->second.key, sizeof(it->second.key),
             (unsigned char*)data.data(), data.size(), mac, &mac_len);

        // Return hex-encoded token
        std::string token;
        token.reserve(64);
        for (unsigned int i = 0; i < mac_len; i++) {
            char hex[3];
            snprintf(hex, sizeof(hex), "%02x", mac[i]);
            token += hex;
        }
        return from_service + ":" + token;
    }

    bool verify_auth_token(const std::string& from_service,
                           const std::string& to_service,
                           const std::string& payload,
                           const std::string& token) {
        std::string expected = create_auth_token(from_service, to_service, payload);
        if (expected.empty()) return false;
        return expected == token;
    }
};

class SearchIndexService {
private:
    std::unordered_map<std::string, std::vector<std::string>> index_;
    CrossServiceAuthenticator* auth_;
    std::string service_id_;

public:
    SearchIndexService(CrossServiceAuthenticator* auth, const std::string& id)
        : auth_(auth), service_id_(id) {
        auth_->register_service(service_id_);
    }

    bool ingest_document(const std::string& caller_service,
                         const std::string& token,
                         const std::string& doc_id,
                         const std::vector<std::string>& terms) {
        std::string payload = "ingest:" + doc_id;
        if (!auth_->verify_auth_token(caller_service, service_id_, payload, token)) {
            return false;
        }
        for (const auto& term : terms) {
            index_[term].push_back(doc_id);
        }
        return true;
    }

    std::vector<std::string> query(const std::string& caller_service,
                                    const std::string& token,
                                    const std::string& term) {
        std::string payload = "query:" + term;
        if (!auth_->verify_auth_token(caller_service, service_id_, payload, token)) {
            return {};
        }
        auto it = index_.find(term);
        if (it != index_.end()) return it->second;
        return {};
    }
};

} // namespace search_index

int main() {
    using namespace search_index;

    AuthTokenGenerator generator;
    CrossServiceAuthenticator auth(&generator);

    // Register multiple services - they will get the SAME derived key
    // because epoch never rotates between registrations
    auth.register_service("ingestion-service");
    auth.register_service("query-service");
    auth.register_service("admin-service");

    SearchIndexService search_svc(&auth, "search-index");

    // Normal operation: ingestion service adds documents
    std::string ingest_token = auth.create_auth_token(
        "ingestion-service", "search-index", "ingest:doc001");
    search_svc.ingest_document("ingestion-service", ingest_token,
                               "doc001", {"hello", "world"});

    // Normal query
    std::string query_token = auth.create_auth_token(
        "query-service", "search-index", "query:hello");
    auto results = search_svc.query("query-service", query_token, "hello");

    std::cout << "Query results for 'hello': " << results.size() << " docs" << std::endl;
    return 0;
}
